const body = $input.first().json;
const initial = (body.initial || []).map(x => ({...x, kind: 'initial'}));
const followup = (body.followup || []).map(x => ({...x, kind: 'followup'}));
const all = [...initial, ...followup];
return all.map(x => ({ json: x }));

const body = $('Fetch Due').first().json;
const initial = body.initial || [];
const followup = body.followup || [];
const reminders = body.send_reminders || [];
const total = initial.length + followup.length + reminders.length;
if (!total) return [];
const line = (x) => `<tr><td style="padding:4px 10px 4px 0;color:#6b7280;font:13px -apple-system,sans-serif">${x.to}</td><td style="padding:4px 0;font:13px -apple-system,sans-serif">${x.subject}</td></tr>`;
const reminderLine = (x) => `<tr><td style="padding:4px 10px 4px 0;color:#6b7280;font:13px -apple-system,sans-serif">${x.artist_name}</td><td style="padding:4px 0;font:13px -apple-system,sans-serif">${x.venue}${x.show_date ? ' — ' + x.show_date : ''}</td></tr>`;
let html = '<div style="font-family:-apple-system,sans-serif">';
if (initial.length) {
  html += `<p><b>${initial.length} initial advance${initial.length===1?'':'s'} drafted</b></p><table>${initial.map(line).join('')}</table>`;
}
if (reminders.length) {
  html += `<p style="margin-top:14px"><b>${reminders.length} ready to send — 21 days out, draft already in Gmail</b></p><table>${reminders.map(reminderLine).join('')}</table>`;
}
if (followup.length) {
  html += `<p style="margin-top:14px"><b>${followup.length} follow-up${followup.length===1?'':'s'} drafted (7 days out, no response)</b></p><table>${followup.map(line).join('')}</table>`;
}
html += '<p style="margin-top:14px">Drafts are in Gmail, unsent \u2014 review and send.</p></div>';
const parts = [];
if (initial.length) parts.push(`${initial.length} initial`);
if (reminders.length) parts.push(`${reminders.length} ready to send`);
if (followup.length) parts.push(`${followup.length} follow-up`);
const subject = `Advance update — ${parts.join(', ')}`;
return [{ json: { subject, html } }];
